*{box-sizing:border-box;margin:0;padding:0}:root{--red:#e21b23;--red2:#b81017;--bg:#f4f5f7;--card:#fff;--text:#171717;--muted:#777;--border:#e3e5e8;--side:#090909;--shadow:0 8px 28px rgba(0,0,0,.07)}body.dark{--bg:#101010;--card:#191919;--text:#f5f5f5;--muted:#aaa;--border:#303030;--shadow:0 12px 35px rgba(0,0,0,.35)}body{font-family:Arial,"Segoe UI",sans-serif;background:var(--bg);color:var(--text);transition:.25s}a{color:inherit;text-decoration:none}button{font:inherit}.app{min-height:100vh;display:grid;grid-template-columns:265px 1fr}.sidebar{position:sticky;top:0;height:100vh;background:var(--side);color:#eee;padding:18px 14px;overflow:auto}.logo{height:105px;display:flex;align-items:center;justify-content:center;border-bottom:1px solid #282828;margin-bottom:14px}.logo img{width:220px;height:92px;object-fit:contain}.nav-title{padding:13px 12px 7px;color:#777;font-size:11px}.nav a{display:flex;align-items:center;gap:11px;padding:12px;border-radius:9px;margin:3px 0;font-size:14px}.nav a:hover,.nav a.active{background:var(--red);color:#fff}.nav .icon{width:22px;text-align:center}.nav .badge{margin-inline-start:auto;background:#fff;color:var(--red);min-width:21px;height:21px;display:grid;place-items:center;border-radius:20px;font-size:10px}.main{min-width:0}.topbar{height:75px;display:flex;align-items:center;justify-content:space-between;gap:15px;padding:0 3%;background:var(--card);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:40}.top-start{display:flex;align-items:center;gap:13px}.menu-btn{display:none;border:0;background:none;color:var(--text);font-size:24px;cursor:pointer}.topbar h1{font-size:21px}.topbar small{display:block;color:var(--muted);margin-top:4px}.top-tools{display:flex;gap:8px;align-items:center}.tool{height:40px;padding:0 12px;border:1px solid var(--border);border-radius:9px;background:var(--card);color:var(--text);cursor:pointer}.admin{display:flex;align-items:center;gap:9px;padding-inline-start:10px}.avatar{width:38px;height: