over{border-color:var(--red);color:var(--red)}.action span{display:block;font-size:24px;margin-bottom:8px}.stock-item{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 18px;border-bottom:1px solid var(--border)}.stock-item p{font-size:13px}.stock-item small{color:var(--muted)}.low{color:var(--red);font-weight:bold}.overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:80}
