<script>const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];let lang=localStorage.adminLanguage||'ar',theme=localStorage.adminTheme||'light';const tr={ar:{main:'الرئيسية',dashboard:'لوحة التحكم',store:'إدارة المتجر',products:'المنتجات',import:'استيراد المنتجات',orders:'الطلبات',customers:'العملاء',categories:'الأقسام',coupons:'الكوبونات',points:'نقاط لمسة',sales:'المبيعات',pos:'نقطة البيع',reports:'التقارير',expenses:'المصروفات والخزنة',system:'النظام',settings:'الإعدادات',viewStore:'عرض المتجر',admin:'المدير',welcome:'مرحبًا بك في لمسة أنوثة',welcomeText:'إليك ملخص أداء المتجر اليوم.',addProducts:'+ إضافة منتجات',today:'اليوم',newOrders:'طلبات جديدة',todaySales:'مبيعات اليوم (ر.ع)',totalProducts:'إجمالي المنتجات',totalCustomers:'إجمالي العملاء',latestOrders:'أحدث الطلبات',viewAll:'عرض الكل',orderNo:'رقم الطلب',customer:'العميل',amount:'المبلغ',orderStatus:'الحالة',noOrders:'لا توجد طلبات حتى الآن',quickActions:'إجراءات سريعة',newCoupon:'كوبون جديد',stockAlerts:'تنبيهات المخزون',stockGood:'لا توجد تنبيهات حاليًا'},en:{main:'Main',dashboard:'Dashboard',store:'Store Management',products:'Products',import:'Import Products',orders:'Orders',customers:'Customers',categories:'Categories',coupons:'Coupons',points:'Lamset Points',sales:'Sales',pos:'Point of Sale',reports:'Reports',expenses:'Expenses & Treasury',system:'System',settings:'Settings',viewStore:'View Store',admin:'Admin',welcome:'Welcome to Lamset Anotha',welcomeText:"Here is today's store performance summary.",addProducts:'+ Add Products',today:'Today',newOrders:'New orders',todaySales:'Today sales (OMR)',totalProducts:'Total products',totalCustomers:'Total customers',latestOrders:'Latest orders',viewAll:'View all',orderNo:'Order no.',customer:'Customer',amount:'Amount',orderStatus:'Status',noOrders:'No orders yet',quickActions:'Quick actions',newCoupon:'New coupon',stockAlerts:'Stock alerts',stockGood:'No alerts currently'}};function applyTheme(){document.body.classList.toggle('dark',theme==='dark');q('#theme').textContent=theme==='dark'?'☀':'☾'}function applyLang(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';q('#language').textContent=lang==='ar'?'English':'العربية';qa('[data-t]').forEach(e=>{let v=tr[lang][e.dataset.t];if(v)e.textContent=v});q('#today').textContent=new Intl.DateTimeFormat(lang==='ar'?'ar-OM':'en-GB',{dateStyle:'full'}).format(new Date())}q('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';localStorage.adminTheme=theme;applyTheme()};q('#language').onclick=()=>{lang=lang==='ar'?'en':'ar';localStorage.adminLanguage=lang;applyLang()};q('#menu').onclick=()=>{q('#sidebar').classList.toggle('open');q('#overlay').classList.toggle('open')};q('#overlay').onclick=()=>{q('#sidebar').classList.remove('open');q('#overlay').classList.remove('open')};applyTheme();applyLang();</script></body></html>
